using System.Security.Cryptography;
namespace SimplexLawFirm.Services.Storage;
public sealed class ExternalEvidenceStorage(IWebHostEnvironment environment) {
    private readonly string root = Path.Combine(environment.ContentRootPath,"App_Data","SecureExternalEvidence");
    public async Task<(string Path,string Type,long Size,string Hash,string Name)> StoreAsync(long requestId,IFormFile file,CancellationToken ct) { if(file.Length is <=0 or >10*1024*1024) throw new InvalidDataException("Files must be 1 byte to 10 MB."); var header=new byte[8]; await using var input=file.OpenReadStream(); var read=await input.ReadAsync(header,ct); input.Position=0; var type=header.AsSpan(0,read).StartsWith("%PDF-"u8)?"application/pdf":read>=3&&header[0]==255&&header[1]==216&&header[2]==255?"image/jpeg":header.AsSpan(0,read).StartsWith(new byte[]{137,80,78,71,13,10,26,10})?"image/png":null; if(type is null) throw new InvalidDataException("Only PDF, JPEG and PNG files are accepted."); var relative=$"{requestId}/{Guid.NewGuid():N}.bin"; var full=Path.Combine(root,relative); Directory.CreateDirectory(Path.GetDirectoryName(full)!); await using var output=new FileStream(full,FileMode.CreateNew,FileAccess.Write,FileShare.None); using var sha=SHA256.Create(); await input.CopyToAsync(output,ct); input.Position=0; var hash=Convert.ToHexString(await sha.ComputeHashAsync(input,ct)); return(relative,type,file.Length,hash,Path.GetFileName(file.FileName)); }
    public Task<Stream> OpenReadAsync(string relativePath,CancellationToken ct=default) { var full=Path.GetFullPath(Path.Combine(root,relativePath)); var safeRoot=Path.GetFullPath(root)+Path.DirectorySeparatorChar; if(!full.StartsWith(safeRoot,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException(); return Task.FromResult<Stream>(new FileStream(full,FileMode.Open,FileAccess.Read,FileShare.Read)); }
}
